        'tool-error': ['unknown'],
        'protocol-error': ['invalid-request', 'invalid-parameters', 'method-unavailable', 'publication-outcome-unknown', 'unknown'],
        'invalid-tool-response': ['unknown'],
        'evidence-unavailable': ['unknown'],
